#define STRICT_LIBRARY
#include "strict.cpp"
// A cycle of length 4 has exactly one reversible non-pawn move by each colour, then both undo.
struct Cyc{Move a,b;};
bool clearback(const Tab&t,const Pos&p,int i,int to){int a=t.t[i],z=p.s[i];if(a==K||a==N)return true;int x=to%8-z%8,y=to/8-z/8,step=(x>0)-(x<0)+8*((y>0)-(y<0));B o=occ(t,p);for(int q=z+step;q!=to;q+=step)if(o&bit(q))return false;return true;}
bool four(int id,Pos p,Cyc* out=nullptr){auto&t=ts[id];if(p.ep||t.v[enc(t,p)]!=0)return false;bool found=false;moves(t,p,[&](Move a,Pos q){if(found||a.cap>=0||a.pr||t.t[a.i]==P)return;q.turn=1-p.turn;q.ep=0;if(t.v[enc(t,q)]!=0)return;moves(t,q,[&](Move b,Pos r){if(found||b.cap>=0||b.pr||t.t[b.i]==P)return;r.turn=p.turn;r.ep=0;if(t.v[enc(t,r)]!=0)return;Pos s=r;if((occ(t,r)&bit(p.s[a.i]))||!clearback(t,r,a.i,p.s[a.i]))return;s.s[a.i]=p.s[a.i];if(att(t,s,s.s[p.turn],1-p.turn,occ(t,s)))return;s.turn=1-p.turn;if(t.v[enc(t,s)]!=0)return;if((occ(t,s)&bit(p.s[b.i]))||!clearback(t,s,b.i,p.s[b.i]))return;Pos x=s;x.s[b.i]=p.s[b.i];if(att(t,x,x.s[q.turn],p.turn,occ(t,x)))return;found=true;if(out)*out={a,b};});});return found;}
void repeat_main(){init();setup();load();loadD();atomic<int> job{0};mutex mu;ofstream f("repeat4_stats.tsv"),ex("repeat4_examples.tsv"),un("repeat4_unresolved.tsv");vector<thread>th;for(int w=0;w<3;w++)th.emplace_back([&]{for(;;){int id=job++;if(id>=int(ts.size()))break;auto&t=ts[id];long long le8=0,high=0,direct=0,inf=0,inf4=0;map<int,pair<long long,long long>>h;vector<U> unresolved;string example,infex;for(U a=0;a<(U)t.sz;a++){if(pc(t.v[a])!=0)continue;D d=ds[id][a];if(d<=8){le8++;continue;}high++;inf+=d==INF;Cyc c;Pos p=dec(t,a);bool b=four(id,p,&c);h[d].first++;if(b){direct++;inf4+=d==INF;h[d].second++;string str=fen(t,p)+"\t"+uci(p,c.a)+" "+uci(p,c.b); // reconstruct second UCI using original square, unchanged by first
string aa=uci(p,c.a),bb=uci(p,c.b);str=fen(t,p)+"\t"+aa+" "+bb+" "+aa.substr(2)+aa.substr(0,2)+" "+bb.substr(2)+bb.substr(0,2)+"\t"+to_string(d);if(example.empty())example=str;if(d==INF&&infex.empty())infex=str;}else unresolved.push_back(a);}lock_guard<mutex>lk(mu);f<<t.name<<'\t'<<le8<<'\t'<<high<<'\t'<<direct<<'\t'<<inf<<'\t'<<inf4<<'\n';f.flush();for(U a:unresolved)un<<t.name<<'\t'<<a<<'\t'<<ds[id][a]<<'\n';un.flush();if(!example.empty())ex<<t.name<<'\t'<<example<<'\n';if(!infex.empty())ex<<t.name<<'\t'<<infex<<'\n';ex.flush();cerr<<t.name<<" repeat "<<high<<" direct "<<direct<<" inf "<<inf<<" inf4 "<<inf4<<endl;}});for(auto&x:th)x.join();}

#ifndef REPEAT_LIBRARY
int main(){repeat_main();}
#endif
